//! `amcrax`: command-line front end of the AmCraX engine.
//!
//! `verify <target>` compares the Rust engine with the golden tables generated by the Python
//! reference and can write the machine-readable comparison report.

mod verify;

use amcrax_engine::data::DataRoot;
use amcrax_engine::verify as ev;
use std::collections::BTreeMap;
use std::path::{Path, PathBuf};
use std::process::ExitCode;

const USAGE: &str = "\
amcrax: AmCraX engine command-line interface

USAGE:
    amcrax --version
    amcrax --help
    amcrax verify <target> [--golden <dir>] [--root <repo>] [--report <file.json>]

VERIFY TARGETS:
    numerics    golden tables of amcrax-numerics (default dir rust/golden/numerics)
    thermo      stage 1: data loading parity and thermodynamics (rust/golden/stage1)

    --root      repository root (default $AMCRAX_ROOT, else . or ..)
    --report    write the comparison report (JSON: per quantity the number of cases, the maximum
                deviation, the gate, pass or fail)
";

#[derive(Debug, PartialEq, Eq)]
enum Command {
    Version,
    Help,
    Verify {
        target: String,
        golden: Option<PathBuf>,
        root: Option<PathBuf>,
        report: Option<PathBuf>,
    },
}

fn parse_args(args: &[String]) -> Result<Command, String> {
    let mut it = args.iter();
    match it.next().map(String::as_str) {
        None | Some("-h") | Some("--help") | Some("help") => Ok(Command::Help),
        Some("-V") | Some("--version") | Some("version") => Ok(Command::Version),
        Some("verify") => {
            let mut target = None;
            let mut golden = None;
            let mut root = None;
            let mut report = None;
            while let Some(a) = it.next() {
                match a.as_str() {
                    "--golden" => {
                        golden = Some(PathBuf::from(
                            it.next().ok_or("--golden needs a directory")?,
                        ))
                    }
                    "--root" => {
                        root = Some(PathBuf::from(it.next().ok_or("--root needs a directory")?))
                    }
                    "--report" => {
                        report = Some(PathBuf::from(it.next().ok_or("--report needs a file")?))
                    }
                    s if s.starts_with('-') => return Err(format!("unknown option {s}")),
                    s => {
                        if target.is_some() {
                            return Err(format!("unexpected argument {s}"));
                        }
                        target = Some(s.to_string());
                    }
                }
            }
            let target = target.ok_or("verify needs a target (numerics, thermo)")?;
            Ok(Command::Verify {
                target,
                golden,
                root,
                report,
            })
        }
        Some(other) => Err(format!("unknown command {other}")),
    }
}

fn default_golden_dir(root: &Path, name: &str) -> PathBuf {
    let p = root.join("rust").join("golden").join(name);
    if p.is_dir() {
        return p;
    }
    let alt = PathBuf::from("golden").join(name);
    if alt.is_dir() { alt } else { p }
}

fn write_report(path: &Path, reports: &[ev::Report]) -> Result<(), String> {
    let mut meta = BTreeMap::new();
    meta.insert(
        "engine_version".to_string(),
        serde_json::Value::String(amcrax_engine::ENGINE_VERSION.to_string()),
    );
    for k in [
        "GITHUB_RUN_ID",
        "GITHUB_SHA",
        "GITHUB_REF_NAME",
        "RUNNER_OS",
    ] {
        if let Ok(v) = std::env::var(k) {
            meta.insert(k.to_lowercase(), serde_json::Value::String(v));
        }
    }
    if let Some(dir) = path.parent()
        && !dir.as_os_str().is_empty()
    {
        std::fs::create_dir_all(dir).map_err(|e| e.to_string())?;
    }
    std::fs::write(path, ev::report_json(reports, meta) + "\n").map_err(|e| e.to_string())
}

fn run_engine_target(
    target: &str,
    root: &Path,
    golden: Option<PathBuf>,
) -> Result<Vec<ev::Report>, String> {
    match target {
        "thermo" => {
            let dir = golden.unwrap_or_else(|| default_golden_dir(root, "stage1"));
            let g = ev::Golden::open(&dir).map_err(|e| e.to_string())?;
            let data = ev::stage1::data(&DataRoot::new(root), &g).map_err(|e| e.to_string())?;
            let thermo = ev::stage1::thermo(&g).map_err(|e| e.to_string())?;
            Ok(vec![data, thermo])
        }
        other => Err(format!(
            "unknown target {other} (available: numerics, thermo)"
        )),
    }
}

fn main() -> ExitCode {
    let args: Vec<String> = std::env::args().skip(1).collect();
    match parse_args(&args) {
        Ok(Command::Version) => {
            println!("amcrax {}", amcrax_engine::ENGINE_VERSION);
            ExitCode::SUCCESS
        }
        Ok(Command::Help) => {
            print!("{USAGE}");
            ExitCode::SUCCESS
        }
        Ok(Command::Verify {
            target,
            golden,
            root,
            report,
        }) => {
            let root = root.unwrap_or_else(ev::default_repo_root);
            if target == "numerics" {
                let dir = golden.unwrap_or_else(|| default_golden_dir(&root, "numerics"));
                return match verify::numerics(&dir) {
                    Ok(r) => {
                        print!("{}", r.render());
                        if r.passed() {
                            ExitCode::SUCCESS
                        } else {
                            ExitCode::FAILURE
                        }
                    }
                    Err(e) => {
                        eprintln!("amcrax verify numerics: {e}");
                        ExitCode::from(2)
                    }
                };
            }
            match run_engine_target(&target, &root, golden) {
                Ok(reports) => {
                    for r in &reports {
                        print!("{}", r.render());
                    }
                    if let Some(p) = report {
                        if let Err(e) = write_report(&p, &reports) {
                            eprintln!("amcrax verify: cannot write report {}: {e}", p.display());
                            return ExitCode::from(2);
                        }
                        println!("report written to {}", p.display());
                    }
                    if reports.iter().all(ev::Report::passed) {
                        ExitCode::SUCCESS
                    } else {
                        ExitCode::FAILURE
                    }
                }
                Err(e) => {
                    eprintln!("amcrax verify {target}: {e}");
                    ExitCode::from(2)
                }
            }
        }
        Err(e) => {
            eprintln!("amcrax: {e}\n\n{USAGE}");
            ExitCode::from(2)
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn args(v: &[&str]) -> Vec<String> {
        v.iter().map(|s| s.to_string()).collect()
    }

    #[test]
    fn parses_commands() {
        assert_eq!(parse_args(&args(&["--version"])), Ok(Command::Version));
        assert_eq!(parse_args(&args(&[])), Ok(Command::Help));
        assert_eq!(
            parse_args(&args(&["verify", "numerics", "--golden", "g"])),
            Ok(Command::Verify {
                target: "numerics".into(),
                golden: Some(PathBuf::from("g")),
                root: None,
                report: None,
            })
        );
        assert_eq!(
            parse_args(&args(&["verify", "thermo", "--report", "r.json"])),
            Ok(Command::Verify {
                target: "thermo".into(),
                golden: None,
                root: None,
                report: Some(PathBuf::from("r.json")),
            })
        );
        assert!(parse_args(&args(&["verify"])).is_err());
        assert!(parse_args(&args(&["verify", "a", "b"])).is_err());
        assert!(parse_args(&args(&["frobnicate"])).is_err());
    }
}
